import * as React from 'react';
import { cn } from '@/lib/utils';

export type TimelineItem = {
  title: string;
  /** Period/date label (e.g. "2023 — Present"). */
  period?: string;
  description?: string;
  icon?: React.ReactNode;
  /** Muted items render dimmed (upcoming/archived). */
  muted?: boolean;
};

export type TimelineProps = Omit<React.OlHTMLAttributes<HTMLOListElement>, 'children'> & {
  items: TimelineItem[];
};

/**
 * Vertical chronology (experience, activity, audit trail). Renders an
 * ordered list with a connector rule, so the sequence is conveyed
 * structurally instead of by decoration alone.
 */
export const Timeline = React.forwardRef<HTMLOListElement, TimelineProps>(function Timeline(
  { items, className, ...props },
  ref
) {
  return (
    <ol ref={ref} className={cn('relative flex flex-col gap-6', className)} {...props}>
      {items.map((item, index) => (
        <li key={`${item.title}-${index}`} className="relative flex gap-4">
          <div className="flex flex-col items-center">
            <span
              aria-hidden="true"
              className={cn(
                'mt-1 flex h-3 w-3 shrink-0 items-center justify-center rounded-full border-2',
                item.muted ? 'border-border bg-background' : 'border-primary bg-primary'
              )}
            />
            {index < items.length - 1 && <span aria-hidden="true" className="mt-1 w-px flex-1 bg-border" />}
          </div>
          <div className={cn('min-w-0 pb-1', item.muted && 'opacity-60')}>
            {item.period && (
              <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{item.period}</p>
            )}
            <p className="text-sm font-semibold">{item.title}</p>
            {item.description && <p className="mt-1 text-sm text-muted-foreground">{item.description}</p>}
            {item.icon && <div className="mt-1 text-muted-foreground [&_svg]:size-4">{item.icon}</div>}
          </div>
        </li>
      ))}
    </ol>
  );
});

{
  "id": "timeline",
  "name": "Timeline",
  "tier": "molecule",
  "description": "Vertical chronology for experience, activity and audit trails, built on an ordered list.",
  "designIntent": "Chronologies communicate order. Rendering them as an ordered list keeps the sequence structural for assistive tech, while the connector rule and dots provide the visual rhythm.",
  "props": [
    {
      "name": "items",
      "type": "{ title: string; period?: string; description?: string; icon?: ReactNode; muted?: boolean }[]",
      "required": true,
      "description": "Ordered timeline entries."
    }
  ],
  "examples": [
    {
      "title": "Experience",
      "code": "<Timeline\n  items={[\n    { title: 'Senior Engineer', period: '2023 — Present', description: 'Platform team' },\n    { title: 'Engineer', period: '2020 — 2023' },\n  ]}\n/>",
      "description": "Period label, title and supporting line per entry."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't reverse the DOM order for newest-first",
      "explanation": "Reverse the array instead so reading order matches visual order.",
      "example": "// Avoid: flex-col-reverse\n// Prefer: items={items.slice().reverse()}"
    }
  ],
  "accessibility": [
    {
      "feature": "Sequence",
      "implementation": "Ordered list semantics",
      "userRequirements": "Keep entries in chronological order in the array"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Periods",
      "guidelines": [
        "Use a consistent format",
        "State Present for ongoing"
      ],
      "goodExamples": [
        "2023 — Present",
        "Jan 2024"
      ],
      "badExamples": [
        "Some time ago"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Card",
      "relationship": "Often embedded in profile/about cards",
      "example": "<Card><CardContent><Timeline items={roles} /></CardContent></Card>"
    }
  ],
  "relatedComponents": [
    "List",
    "Card",
    "Separator"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "timeline",
  "exportName": "Timeline"
}
